def renumber_words(apps, schema_editor):
    """Rejected words used to take a place in the chain. Give them none, and number the accepted ones 0, 1, 2...

    The starting word is the first accepted word, so the chain keeps its order and no two words share a place.
    """
    Word = apps.get_model("games", "GameWord")
    Word.objects.filter(is_valid=False).update(position=None)
    games = Word.objects.filter(is_valid=True).values_list("game_id", flat=True).distinct()
    for game_id in games:
        for index, word in enumerate(Word.objects.filter(game_id=game_id, is_valid=True).order_by("position", "id")):
            if word.position != index:
                word.position = index
                word.save(update_fields=["position"])


